const baseMsg = errorMessages[$json.error_code] || "⚠️ **Authentication Error**

An unexpected authorization error occurred.";
const finalMessage = `${baseMsg}

---
\`Error Code: ${$json.error_code} (${$json.status_code})\``;

return {
  is_authorized: false,
  message: finalMessage
};
